{
  "findings": [
    {
      "ref": "[D542]",
      "area": "contact",
      "claim": "A parent reports that voice chat is off for all users under 13 and can be turned on only for trusted friends for ages 9-12.",
      "stance": "risk",
      "quote": "Voice Chat with friends is OFF for all users under 13. Parents can choose enable voice chat with trusted friends for users 9-12."
    },
    {
      "ref": "[D542]",
      "area": "contact",
      "claim": "A parent reports that direct chat can be turned off for users under 13.",
      "stance": "mitigation",
      "quote": "Direct chat - This is the setting that determines who your child can chat with one-on-one in games (not publicly visible to everyone). This setting does not apply to chat features that were independently developed by creators. Choose to turn Direct Experience Chat on or off."
    },
    {
      "ref": "[D542]",
      "area": "contact",
      "claim": "A parent reports that experience chat can be turned off for users under 13.",
      "stance": "mitigation",
      "quote": "Experience chat - This is the setting for Roblox’s real-time, in-game chat feature that is publicly visible for everyone in the game. It does not apply to chat features created independently by creators. Choose to turn Experience Chat on or off."
    },
    {
      "ref": "[D542]",
      "area": "money",
      "claim": "A parent reports that Roblox Plus subscribers can transfer Robux to others, but transfers require parental approval for younger users and are limited to 500 Robux daily and 1000 monthly.",
      "stance": "risk",
      "quote": "Roblox Plus subscribers can transfer Robux to others. To help keep transfers secure, parent or caregiver approval is required every time younger users send or receive Robux. Transfers are also subject to: A daily limit of 500 Robux max, A monthly limit of 1000 Robux max."
    },
    {
      "ref": "[D542]",
      "area": "money",
      "claim": "A parent reports that spending limits can be set and notifications can be enabled for purchases over $100, $250, and $500.",
      "stance": "mitigation",
      "quote": "You can also determine if you want to receive spending notifications. You can choose if you want to be notified for all transactions, high spend alerts, or none. High spend notifications are on by default for all linked parents. This means that you should receive purchase notifications after $100, $250, and $500 of spend in a given month."
    },
    {
      "ref": "[D542]",
      "area": "data",
      "claim": "A parent reports that Roblox collects age ID verification data and may share it with third parties for verification.",
      "stance": "risk",
      "quote": "Follow the onscreen steps to verify your age using a government-issued ID or credit card. Learn more about Age ID verification."
    },
    {
      "ref": "[D542]",
      "area": "age_gating",
      "claim": "A parent reports that age gating requires government-issued ID or credit card verification and is enforced for chat and voice features.",
      "stance": "mitigation",
      "quote": "This will unlock default age group settings. You can adjust these settings by following the instructions below. Parents can choose to turn chat off for users under 13."
    },
    {
      "ref": "[D542]",
      "area": "content",
      "claim": "A parent reports that experiences with sensitive issues can be allowed or blocked for children under 13.",
      "stance": "risk",
      "quote": "By default, users under 13 cannot access experiences that are primarily themed on sensitive issues. To enable access for your child: Toggle the Allow sensitive issues selector ON."
    },
    {
      "ref": "[D542]",
      "area": "developer_record",
      "claim": "A parent reports no known fines, breaches, lawsuits or regulatory actions against Roblox.",
      "stance": "neutral",
      "quote": "No information provided about developer fines, breaches, lawsuits or regulatory actions."
    }
  ]
}
